"""Generate the single Reeltrip product documentation from the shared screen catalog."""
from pathlib import Path
import html,json,re,subprocess
from spec_explorer import render_explorer
from notification_policy import render_policy, render_message_catalog
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs'
E=lambda value:html.escape(str(value),quote=True)
catalog=json.loads(subprocess.check_output(['node','-e',"global.window={};require('./src/assets/catalog.js');process.stdout.write(JSON.stringify(window.REEL_SCREENS))"],cwd=ROOT,text=True))
state_previews=json.loads((ROOT/'resources/review/screen-states.json').read_text())
for i,s in enumerate(catalog,1):
 s.setdefault('id',f'B-{i:02d}')
 if s['route'] in state_previews:s['statePreviews']=state_previews[s['route']]
def page(title,body):
 toc=''.join(f'<a href="#{slug}">{E(label)}</a>' for slug,label in re.findall(r'<section class="docsection" id="([^"]+)"><h2>([^<]+)</h2>',body))
 toc_html='<nav class="reader-toc" aria-label="문서 목차">'+toc+'</nav>' if toc else ''
 return f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · 릴트립</title><link rel="stylesheet" href="../src/assets/docs.css"><link rel="stylesheet" href="../src/assets/spec-explorer.css"><script defer src="../src/assets/spec-explorer.js"></script><script defer src="../src/assets/spec-inline-preview.js"></script></head><body class="readable-doc"><a class="doc-skip" href="#document">본문으로 이동</a><header class="reader-bar"><a href="index.html"><strong>reeltrip</strong> 문서</a><nav aria-label="문서 메뉴"><a href="product.html">전체 기획</a><a href="specification.html">화면 명세</a><a href="policies.html">공통 정책</a><a href="design-guide.html">디자인 시스템</a><a href="developer-handoff.html">개발 인계</a><a href="../src/frontend/index.html">화면 탐색</a></nav></header><main class="hub" id="document"><header class="reader-title"><p class="spec-kicker">REELTRIP / DOCUMENTATION</p><h1>{E(title)}</h1></header>{toc_html}{body}</main></body></html>'
def section(title,body,slug=''):return '<section class="docsection"'+(' id="'+slug+'"' if slug else '')+'><h2>'+E(title)+'</h2>'+body+'</section>'
plan='''<p>영상과 직접 입력으로 장소를 모으고, 내 여행을 만든 뒤 현지 메이트의 제안을 비교하는 매칭 서비스다.</p><h3>탭별 역할</h3><ul><li>발견: 영상 링크로 장소 찾기 → 선택한 장소를 보관함에 저장. 바로 일정에 넣지 않는다. 저장한 장소는 여행·날짜와 무관한 공용 보관함이며, 영상 추가·장소 추가·장소 관리만 제공한다. 보관함에서 새 여행을 만들거나 내 여행을 선택한 후, 여행 상세의 저장한 장소 선택 기능으로 원하는 날짜에 담는다.</li><li>채팅: 여행 요청·메이트별 대화 목록. 메이트 수수료 결제에 따른 확정 후 양측 모두 대화를 시작하고 여행 완료·취소 또는 마지막 날 자정까지 유지한다. 최근 메시지·시각·상태·역할별 미읽음 표시. 종료된 대화는 읽기 전용. 실제 전송 없는 로컬 시제품.</li><li>내 여행: 여행 생성 카드·우측 상단 저장한 장소 아이콘·다가오는 여행/지난 여행 목록과 예정 여행 없음 안내. 여행 상세는 상단 정보 수정, 지도, 날짜별 일정 시트, 순서 번호와 거리 안내, ＋ 메뉴(저장한 장소·새 장소)로 구성한다. 출발일 수정 시 모든 날짜를 함께 이동한다. 별도 편집 화면 없이 여행 상세에서 장소별 메뉴로 순서 변경·삭제, 날짜 버튼으로 해당 날짜를 수정하며 변경 즉시 자동 저장한다. 새 여행 생성·선택 후 상세 안에서 날짜·장소·순서·메이트 요청을 관리한다. 여행별 일정은 분리 저장하고 장소 보관함은 공유한다. 일정에서 빼도 보관함에는 유지.</li><li>메이트: 도착한 제안 / 제안받기. 제안받기에서 자유 여행 함께하기 또는 내 여행 함께하기를 선택한다. 자유 여행 함께하기는 자유 견적 요청으로, 내 여행 함께하기는 요청 화면의 1단계 여행 목록에서 선택한 후 2단계 요청 내용을 작성하고 신청한다. 여행이 하나여도 선택 단계를 표시하며, 작성 화면에서 여행을 다시 선택할 수 있다. 선택한 여행 ID와 전체 일정을 요청에 보존한다. 자유 견적은 여행 지역·출발일·기간(당일~6박 7일)·인원으로 요청하며 장소 목록은 필요 없다. 내 여행에서는 날짜별 장소가 담긴 전체 여행으로 요청한다. 두 경로 모두 공개 요청 후 복수 제안을 비교·선택한다.</li><li>마이: 프로필 편집·메이트 등록. 설정 아이콘 안에 언어·모드 전환, 알림 설정·차단한 사용자·도움말·약관·회원 탈퇴.</li></ul><p>메이트 프로필은 회원 전용이며 받은 제안의 상대 프로필에서 확인한다. 비회원의 직접 접근은 가입 안내를 표시하고 프로필을 노출하지 않는다.</p><h3>확정 흐름</h3><p>여행 공개 → 메이트들의 일정·가격 제안 → 여행자 선택·예약 요청 → 메이트 확정 대기 → 메이트가 10% 매칭 수수료 결제 → 예약 확정 → 현장에서 여행비 전액 현금 직접 지급.</p><p>240,000원 여행이면 메이트는 플랫폼에 24,000원을 선결제하고, 여행자는 메이트에게 240,000원을 현금으로 직접 지급한다. 플랫폼은 여행비를 수납·송금하지 않는다.</p><h3>현재 구현 범위</h3><p>고객·메이트 동일 앱, 운영자는 별도 웹. 한국어·영어 로컬 시제품. 여러 여행·날짜가 겹치지 않는 복수 공개 요청을 유지하며, 내 여행 전체 일정 또는 자유 견적 요청을 공개한다. 기간과 요청 유형은 제안·예약까지 스냅샷으로 보존한다. 복수 제안을 지원하며 유효한 제안의 수정·중복 발행은 금지한다. 만료 후에만 다시 제안할 수 있다. 실제 영상 분석·인증·DB·PG·이메일·다중 사용자 동기화는 미구현이다.</p>'''
policies='''<ul><li>공개 HTTPS Shorts/Reels 링크와 장소 확인을 지원한다. 실제 추출은 미연동이다.</li><li>요청은 최소 48시간 전·최대 7일이다. 자유 견적은 지역 입력과 기간만으로 시작한다. 내 여행은 날짜 순서와 하루 최대 20곳을 검사한다. 지역별 실제 메이트 공급·영업 가능 여부는 서버 연결 후 검증한다. 숙박 일수는 기간이며 숙소나 24시간 동행을 포함하지 않는다. MVP 영어 동행은 하루 4시간 고정이며 메이트는 일행 전체 금액만 입력한다. 날짜·인원·기존 일정은 요청 스냅샷 그대로 유지한다. 자유 여행에만 날짜별 코스를 입력한다.</li><li>같은 요청에 복수 제안을 보존한다. 동일 메이트의 유효한 제안은 수정·재발행할 수 없다. 만료 후 재발행 시에만 교체하며 고객이 선택한 버전·금액을 예약에 고정한다. 채팅은 일정·금액을 변경하지 않는다.</li><li>여행자 선택만으로 확정하지 않는다. 선택된 메이트의 매칭 수수료 10% 결제 검증 후에만 확정한다.</li><li>여행비는 현장에서 직접 현금으로 지급하며 앱에서 별도 수령 확인을 요구하지 않는다.</li><li>확정 전 철회와 확정 후 즉시 취소를 분리한다. 플랫폼은 여행비 자동 환불을 제공하지 않는다.</li><li>확정 기한은 선택 후 24시간과 출발 시각 중 빠른 시각이다. 결제 유예·노쇼·취소·분쟁은 위 MVP 정책을 적용한다. VAT 처리는 별도 확정한다. 이전 자동 환불률을 적용하지 않는다.</li><li>닉네임 중복 금지: NFKC·공백 제거·소문자 기준. 자신의 기존 이름 유지 허용. 변경 후 재확인과 저장 직전 재검사. 실제 서버 UNIQUE 제약은 별도 구현한다.</li></ul>'''
mate_flow = '<h3>메이트 활동과 확정 관리</h3><p>메이트 GNB: 여행 찾기 / 내 활동 / 채팅 / 마이. 내 활동은 보낸 제안 / 예약 두 탭과 건수로 구분한다. 선택된 제안은 예약 탭으로 이동하고 수수료 결제 대기·예약 확정·완료·취소를 구분한다. 예약이 있으면 예약 탭을 기본으로 열며 사용자가 선택한 탭은 URL에 보존한다. 각 탭의 빈 상태는 아이콘·안내·버튼을 중앙 정렬한다. 결제 대기 상태의 여행 찾기 카드·내 활동 카드·선택된 제안·예약 상세에는 진행 불가(보조) → 예약 확정(주 실행)를 함께 표시한다. 결제 폼의 주 실행은 결제하고 예약 확정으로 표시한다. 진행 불가는 사유 입력 후 진행 거절하기로 제출하며 자동 재모집 안내를 제공한다. 날짜별 복수 예약은 해당 예약을 활성화한 뒤 상태에 맞는 결제·취소·대화를 실행한다. 수수료 금액·상태 확인과 결제는 해당 예약 상세에서 진행한다. 기존 화면 ID와 저장 키는 유지한다.</p><p>선택 시 feeDeadline을 고정한다. 시제품은 선택 후 24시간과 출발 시각 중 빠른 기한을 사용한다. 렌더링과 결제 시 만료를 확인하며 앱이 닫힌 동안 서버 알림이나 자동 작업은 실행되지 않는다. 확정 전 메이트 진행 불가·기한 만료 시 여행 시작 전이면 자동으로 제안 모집을 재개한다. 기존 예약은 bookingHistory에 보존하고 해당 메이트의 제안은 만료시키며 다른 유효한 제안은 즉시 선택 가능하게 유지한다. 여행자에게 해제 사유와 재모집 상태를 안내한다. 여행 시작 시간이 지났으면 자동 재모집하지 않고 일정 변경을 안내한다. 여행자의 직접 철회는 자동 재모집하지 않으며 다른 제안 선택 버튼으로 재개한다.</p><p>결제 화면은 약속 금액·수수료 10%·차감 후 금액(기타 비용 차감 전)을 표시한다. 성공 후 예약 상세에서 채팅으로 만날 장소·날짜별 시간·현금 지급 시점을 확인한다. 동행 관리 카드 없이 예약 상세 맨 아래에 예약 취소 텍스트 버튼을 제공한다. 마지막 날 동행 종료 시각 이후에는 여행 완료 확인을 별도의 주요 버튼으로 표시한다. 현금 수령 확인은 요구하지 않는다. 확정 후 취소는 즉시 cancelled로 처리하며 request도 cancelled로 갱신한다. 여행자 취소는 결제한 매칭 수수료 전액의 환불을 즉시 요청하고 성공하면 refundStatus=completed로 처리한다. 메이트 귀책 취소는 원칙적으로 not_eligible이며 예약 취소 완료는 환불 완료를 의미하지 않는다. 노쇼·반환은 위 MVP 정책을 적용하며 실제 PG 연결·세금 처리는 별도 구현한다.</p><p>가능 날짜 달력은 제공하지 않는다. 메이트가 가능한 요청에 직접 제안하며, 확정 예약과 날짜가 겹치는 제안은 차단한다. 기존 unavailableDates 저장값은 보존하되 제안 가능 여부에 사용하지 않는다. 실서비스는 서버 소유권 검사, 예약 중복 방지, 기한 만료와 PG 웹훅 경합 처리, 결제 멱등성, 금액·통화·주문 검증을 구현해야 한다.</p>'
withdrawal_policy = '<h3>회원 탈퇴</h3><p>마이 → 설정 → 회원 탈퇴. 여행자·메이트 공통으로 삭제 범위와 복구 불가 안내를 확인하고 필수 동의 후 탈퇴한다. 취소 → 탈퇴하기 순서이며 취소 시 데이터를 유지한다. 진행 중인 예약(메이트 확정 대기·확정 포함), 본인의 수수료 반환 처리, 본인이 당사자인 예약 분쟁이 남아 있으면 탈퇴를 제한한다. 상대 메이트의 반환만 남은 여행자의 탈퇴는 제한하지 않는다. 현재 상태 및 한국어·영어 저장본의 예약 이력을 실행 직전에 재검사한다. 프로필·장소·여행·요청·제안·채팅·문의 및 메이트 신청·권한, 본인의 닉네임 점유를 삭제하고 게스트 홈으로 이동한다. 언어 설정과 타인의 닉네임 점유는 유지한다. 저장소 오류 시 완료로 표시하지 않는다. 브라우저 로컬 시제품이며 실제 인증 계정·서버 데이터 삭제는 미연동이다.</p>'
plan += withdrawal_policy
plan += '<h3>MVP 기능 범위</h3><p>외부 예약은 장소별 외부 사이트 링크만 제공한다. 예약 기록 입력·수정·삭제와 앱 내 예약 상태 관리는 제공하지 않는다. 일정에는 거리·도보 추정 시간과 Google Maps 구간 길찾기를 유지한다. 장소별 체류시간 설정·표시, 시작 시간 설정, 방문 시각 자동 계산·표시, 총 체류시간 합산, 다른 날로 이동·메모 입력·여행 후기는 제외한다. 메이트 등록과 알림은 유지한다. 기존 B-* ID와 로컬 저장 키는 보존하며 삭제된 후기·예정 일정 주소는 예약 상세로, 가능 일정은 내 활동으로, 수수료 내역은 예약·수수료 상세로 연결한다.</p>'
plan += '<h3>메이트 활동</h3><p><a href="policies.html#mate-activity">내 활동·예약 확정 정책</a></p>'
policies += '<section id="mate-activity">'+mate_flow+'</section>'
chat_policy = '''<h3 id="chat-mvp">채팅 정책</h3><ul><li><strong>시작:</strong> 메이트가 매칭 수수료를 결제해 확정되면 양측 모두 먼저 1:1 메시지를 보낼 수 있다. 결제 전에는 양측 모두 메시지를 보낼 수 없다.</li><li><strong>이용 기간:</strong> 여행이 확정된 동안 마지막 날 24:00(Asia/Seoul, 다음 날 00:00)까지 대화할 수 있다. 여행 완료 처리 시 즉시 종료한다.</li><li><strong>종료:</strong> 여행 완료, 이용 기간 종료 또는 예약 철회·취소 시 읽기 전용으로 전환한다.</li><li><strong>메시지:</strong> 텍스트 1~1,000자만 지원한다. 빈 메시지는 보낼 수 없으며 사진·파일 첨부는 지원하지 않는다.</li><li><strong>예약 조건:</strong> 만날 장소·시간을 확인하는 용도다. 채팅 합의만으로 선택한 일정·금액은 변경되지 않는다.</li><li><strong>확정:</strong> 예약은 메이트의 10% 매칭 수수료 결제 후 확정되며 양측 모두 대화를 먼저 시작할 수 있다. 여행비는 현장에서 현금으로 직접 지급한다.</li></ul>'''
chat_policy += '<h3>신고·차단 MVP</h3><p>채팅방 더보기에서 사용자 신고·차단·해제를 제공한다. 신고는 사유 선택, 선택 상세(기타는 필수, 최대 1,000자)를 저장하며 같은 신고자의 같은 대화방 중복 신고를 막는다. 차단은 상대 ID 기준으로 다른 대화방에도 적용하고 양쪽 메시지 전송 및 미읽음 표시를 중단한다. 기존 대화와 예약 상태는 유지한다. 설정의 차단한 사용자에서 해제할 수 있다. 빈 목록은 차단 진입 경로를 안내하고, 목록이 있으면 사용자명·차단 중 상태·해제 버튼과 건수를 표시한다. 차단은 예약 취소가 아님을 안내한다. 해제 확인은 취소→차단 해제 순서로 제공하고 취소하면 목록으로 돌아간다. 해제 후 완료 안내와 갱신된 목록을 표시하며 마지막 사용자 해제 시 빈 상태로 전환한다. 상대방의 차단이나 채팅 종료 등 이용 조건으로 해제 후에도 전송이 제한될 수 있음을 확인창에 안내한다. 사용자·메이트 모두 상대를 신고·차단할 수 있다. 신고 관리에서 처리 사유를 남겨 신고를 종결하거나 승인 메이트의 활동을 제한하고 종결한다. 메이트 관리와 신고 상세에서 활동 정지 사유와 종료일을 입력한다. 한국시간 기준 종료일의 다음 날 0시부터 자동 해제되며 메이트 관리에서 조기 해제할 수 있다. 차단 해제 후에도 신고 기록은 유지한다. 같은 브라우저·같은 출처의 로컬 저장소로 동작하며 외부 연동은 사용하지 않는다. 서버 연결 시 실제 사용자 ID, 인증·권한, 양방향 전송 차단 및 신고 처리 절차를 구현해야 한다.</p>'
policies += chat_policy
plan += '<h3>채팅 정책</h3><p>수수료 결제 후 양측 모두 대화 시작 → 여행 마지막 날 24:00까지 이용 → 종료 후 읽기 전용. 여행 완료·철회·취소 시 즉시 종료하며, 채팅은 예약 확정이나 일정·금액 변경을 의미하지 않는다. <a href="policies.html#chat-mvp">채팅 정책 전체 보기</a></p>'
policies += '''<h3 id="signup-access">가입 방법과 로그인</h3><ul><li>가입 화면의 ‘이미 계정이 있나요? 로그인’과 게스트 마이의 로그인으로 기존 회원이 진입한다. signup?mode=signin에서 이메일 또는 소셜 로그인을 선택하고, signup-email?mode=signin에서 이메일 → 코드 확인 순서로 진행한다. 언어 전환과 뒤로 가기에서도 로그인 모드를 유지한다. 현재는 시연 인증이며 실제 계정 조회·이메일 발송·서버 인증은 연결되지 않았다.</li><li>처음 방문한 여행자는 Google·카카오·네이버 간편가입, 이메일 가입, 가입 없이 둘러보기 중 하나를 선택한다.</li><li>간편가입 버튼에는 제공사 로고와 이름을 함께 표시한다. Google은 흰 바탕과 다색 G, 카카오는 노란 바탕과 말풍선, 네이버는 초록 바탕과 N으로 구분한다.</li><li>미리보기에서는 간편가입 버튼을 한 번 누르면 즉시 로그인 상태로 홈에 진입한다. 실제 서비스에서는 각 제공사의 인증이 성공한 뒤 로그인 처리한다.</li><li>이메일 가입은 주소 입력 → 인증 코드 입력 → 가입 완료 순서로 진행한다. 미리보기에서는 시연용 코드로 확인하며, 실제 이메일 발송·검증은 서비스 연동 시 구현한다.</li></ul>
<h3 id="signup-language">가입 언어와 로고</h3><p>가입 화면에서 한국어·영어·중국어 간체·일본어를 선택할 수 있다. 언어 설정에는 현재 언어 이름을 표시하고 선택 목록에는 선택 표시를 둔다. 선택 즉시 가입 화면에 적용하고 가입 후에도 같은 언어로 앱을 연다. 중국어 가입 로고에는 ‘映旅’, 일본어 가입 로고에는 ‘リールトリップ’을 표시한다. 게스트도 마이에서 언어를 변경할 수 있다.</p>
<h3 id="guest-browsing">게스트 열람 범위와 가입 안내</h3><ul><li>‘가입 없이 둘러보기’를 선택하면 발견 홈을 연다. 발견·내 여행·메이트·채팅·마이 탭 이동, 추천 경로와 예시 장소 열람, 공개 예시 열람은 가입 없이 허용한다. 실제 제안 상대 메이트 프로필은 회원 전용이다.</li><li>장소 추가·저장, 여행 일정 만들기·수정, 메이트 요청 등 회원 기능을 실행할 때 가입을 안내한다. 탭을 여는 것만으로는 안내를 띄우지 않는다. 게스트의 개인 데이터는 저장하지 않는다.</li><li>가입 안내에는 여행을 연상시키는 이미지나 아이콘과 친근한 문구를 사용한다. ‘가입하기’는 가입 화면으로, ‘계속 둘러보기’는 직전에 보던 공개 화면으로 연결한다.</li><li>게스트 마이에는 게스트 상태, 가입 버튼, 언어 설정을 표시한다. 프로필 편집과 별도 이용안내 메뉴는 제공하지 않는다. 알림 진입점을 마이 메뉴에 중복 배치하지 않는다.</li><li>추천 경로의 장소 카드는 사진 옆에 장소명과 주소를 묶어서 표시한다. 좁은 화면에서도 긴 주소가 카드 안에서 줄바꿈되도록 한다.</li></ul>
<h3 id="signup-preview">가입 화면 미리보기</h3><p>프로젝트 최상위 index.html을 브라우저에서 직접 열면 가입 화면으로 진입할 수 있어야 한다. 별도 로컬 서버를 시작하거나 포트 주소를 입력하는 절차는 필요하지 않다.</p>'''
